const items = $input.all();
const config = $('Config').first().json;
const DOMINIO_PROPRIO = 'ateliersenzapari.com.br';

const PALAVRAS_CRITICAS = ['contrato', 'pagamento', 'urgente', 'hapvida', 'btg', 'sefaz'];

function normalizar(texto) {
  return (texto || '')
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const resultado = [];
for (const item of items) {
  const json = item.json;
  const remetente = (json.from && json.from.value && json.from.value[0] && json.from.value[0].address) || json.from || '';

  // Ignora e-mails internos (nossos proprios encaminhamentos/rascunhos) para nao notificar duplicado
  if (remetente.toLowerCase().includes(DOMINIO_PROPRIO)) continue;

  const assunto = json.subject || '';
  const corpo = json.textPlain || json.text || '';
  const textoNorm = normalizar(assunto + ' ' + corpo);

  const critico = PALAVRAS_CRITICAS.some((p) => textoNorm.includes(p));

  resultado.push({
    json: {
      critico,
      remetente,
      assunto,
      previa: corpo.substring(0, 150),
      numeroWhatsappLuciano: config.numeroWhatsappLuciano,
      whatsappPhoneNumberId: config.whatsappPhoneNumberId
    }
  });
}

return resultado;
